#!/usr/bin/env python3
"""hexn_config_v1: Hex-N memory settings, worked out at creation time (Alan, 28 Oct 2026: bitmap size, write batching and the shortcut are creation-time settings, some typed in, some calculated from what the user supplies; like the UniCell assembler, which takes a MAN file for the card's capabilities and refuses a design that does not fit).
Reads a MAN file (docs/man/*.man.json: which tiers the card has, block RAM size) plus the user's choices, and writes:
  <out>/hexn_config.json   every setting, where each came from (`given`, `default`, `derived`, `override`) and the fit check
  <out>/hexn_config.vh     Verilog localparams for the RTL (nothing in the RTL reads it yet; store v5 and the tiers are not built on it)
Tiers follow the card: a card with an SD slot keeps long-term patterns on the card; otherwise the main RAM holds them (Kintex plan), then JTAG. The fast table is always block RAM; the next level is the RAM (Tang: the embedded SDRAM).
Derived: contexts_on_card = patterns_on_card / 2.4 (measured in the synthetic world: 4,828 entries over 2,033 contexts); bitmap_bits = max(4096, next power of two >= bitmap_factor x contexts_on_card); entries_per_sector = 512 / entry_bytes; batch_sectors = max(2, ceil(bitmap_bits / 16384)).
HEURISTICS, NOT MEASURED: patterns_on_card 4000 (the size of the synthetic world), bitmap_factor 32, entry_bytes 8, batch_sectors rule. The model (tools/hexn_layer3_tiers_v1.py) supports a bitmap of 16,384 to 65,536 bits at the Tang's scale only. Fit check: block RAM bits needed (rounded up to whole 18 Kbit blocks per memory) against 80% of the card's block RAM minus what the chip already uses (--bram-used-blocks, default 14 = core v9 with store v5 on the Tang, measured; that already includes a fast table of 2,048 entries at 8 bytes, so only a larger fast table adds blocks). A MAN file without a block RAM size (the Kintex one has `total: null`) needs --bram-kbits."""
import argparse, json, math, os, sys
ROOT = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
BLOCK_BITS = 18 * 1024
ENTRIES_PER_CONTEXT = 4828 / 2033
def p2(n): return 1 << max(0, math.ceil(math.log2(max(1, n))))
def build(a):
    man = json.load(open(a.man)); cap = man.get("capabilities", {}); dev = man.get("device", {}); S = {}
    def put(k, v, src): S[k] = {"value": v, "from": src}
    def opt(k, given, default):
        if given is None: put(k, default, "default")
        else: put(k, given, "given")
    kb = a.bram_kbits if a.bram_kbits is not None else (dev.get("bram") or {}).get("kbits_datasheet")
    if not kb: raise SystemExit("this MAN file has no block RAM size: give --bram-kbits")
    put("bram_kbits", kb, "override" if a.bram_kbits is not None else "MAN")
    sd = bool(cap.get("sd_card")); sdram = bool(cap.get("sdram_embedded")); ddr = a.ddr_mb is not None
    put("card_tier", "sd" if sd else "ram", "MAN"); put("ram_tier", "sdram" if sdram else ("ddr" if ddr else "none"), "MAN" if sdram else "given")
    ram_bytes = 8 * 1024 * 1024 if sdram else ((a.ddr_mb or 0) * 1024 * 1024)
    opt("fast_entries", a.fast_entries, 2048); opt("entry_bytes", a.entry_bytes, 8); opt("lookback", a.lookback, 4)
    opt("patterns_on_card", a.patterns_on_card, 4000); opt("bitmap_factor", a.bitmap_factor, 32); put("shortcut", bool(a.shortcut), "given" if a.shortcut is not None else "default")
    v = lambda k: S[k]["value"]
    put("ram_entries", ram_bytes // v("entry_bytes") if ram_bytes else 0, "derived")
    put("contexts_on_card", math.ceil(v("patterns_on_card") / ENTRIES_PER_CONTEXT), "derived")
    if a.bitmap_bits is not None: put("bitmap_bits", p2(a.bitmap_bits), "override")
    else: put("bitmap_bits", max(4096, p2(v("bitmap_factor") * v("contexts_on_card"))), "derived")
    put("entries_per_sector", 512 // v("entry_bytes"), "derived")
    if a.batch_sectors is not None: put("batch_sectors", a.batch_sectors, "override")
    else: put("batch_sectors", max(2, math.ceil(v("bitmap_bits") / 16384)), "derived")
    mems = {"fast_table": v("fast_entries") * v("entry_bytes") * 8, "presence_bitmap": v("bitmap_bits"), "batch_buffer": v("batch_sectors") * 512 * 8}
    blocks = {k: math.ceil(b / BLOCK_BITS) for k, b in mems.items()}
    blocks["fast_table"] = max(0, blocks["fast_table"] - math.ceil(2048 * 8 * 8 / BLOCK_BITS))   # the 14 used blocks already hold store v5's 2,048 entry slots; only growth beyond that counts
    need = sum(blocks.values()); total = int(kb * 1024 // BLOCK_BITS)
    used = a.bram_used_blocks; room = int(total * 0.8) - used
    fit = {"block_ram_blocks_each": blocks, "needed": need, "card_total_blocks": total, "already_used": used, "room_at_80_percent": room, "fits": need <= room}
    return S, fit
def vh(S):
    L = ["// hexn_config.vh -- GENERATED by tools/hexn_config_v1.py. Do not hand-edit."]
    for k, d in S.items():
        x = d["value"]; x = (1 if x else 0) if isinstance(x, bool) else x
        L.append("localparam HEXN_%s = %s;" % (k.upper(), x if isinstance(x, int) else '"%s"' % x))
    return "\n".join(L) + "\n"
def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--man", required=True); ap.add_argument("--out", required=True)
    for n in ("fast-entries", "entry-bytes", "lookback", "patterns-on-card", "bitmap-factor", "bitmap-bits", "batch-sectors", "ddr-mb", "bram-used-blocks", "bram-kbits"):
        ap.add_argument("--" + n, type=int if n != "bram-kbits" else float, default=14 if n == "bram-used-blocks" else None)
    ap.add_argument("--shortcut", action="store_true", default=None, help="answer from the fast table when a context has followers there (costs a little accuracy on rare patterns)")
    a = ap.parse_args(argv); S, fit = build(a); os.makedirs(a.out, exist_ok=True)
    json.dump({"settings": S, "fit": fit}, open(os.path.join(a.out, "hexn_config.json"), "w"), indent=1); open(os.path.join(a.out, "hexn_config.vh"), "w").write(vh(S))
    for k, d in S.items(): print("%-18s %-10s (%s)" % (k, d["value"], d["from"]))
    print("block RAM: %s -> needs %d of room %d (card has %d, %d already used, ceiling 80%%): %s" % (fit["block_ram_blocks_each"], fit["needed"], fit["room_at_80_percent"], fit["card_total_blocks"], fit["already_used"], "FITS" if fit["fits"] else "DOES NOT FIT"))
    return 0 if fit["fits"] else 1
if __name__ == "__main__":
    sys.exit(main())
